module max_prefixes (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] k,\n    input [7:0] s,\n    input [7:0] t,\n    output reg [15:0] ans,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    reg [7:0] cur;\n    reg [3:0] index;\n    reg [1:0] state;\n    wire subtract_s;\n    wire subtract_t;\n    wire signed [9:0] raw_next;\n    wire [7:0] clamped_cur;\n    wire [15:0] next_ans;\n    wire signed [9:0] k_signed;\n    \n    assign subtract_s = s[index];\n    assign subtract_t = (t[index] == 1'b0) ? 1'b1 : 1'b0;\n    assign k_signed = $signed({1'b0, k});\n    assign raw_next = ($signed({1'b0, cur}) * 10'sd2) - subtract_s - subtract_t;\n    assign clamped_cur = (raw_next > k_signed) ? k : ((raw_next < 10'sd0) ? 8'd0 : raw_next[7:0]);\n    assign next_ans = ans + clamped_cur;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            cur <= 8'd1;\n            ans <= 16'd0;\n            index <= 4'd0;\n            state <= IDLE;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        cur <= 8'd1;\n                        ans <= 16'd0;\n                        index <= 4'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                COMPUTE: begin\n                    cur <= clamped_cur;\n                    ans <= next_ans;\n                    index <= index + 4'd1;\n                    if (index == 4'd7) begin\n                        state <= IDLE;\n                        done <= 1'b1;\n                    end\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule